import {login,logout,getUser,handleAuthCallback,acceptInvite,updateUser,requestPasswordRecovery} from '@netlify/identity';
import Papa from 'papaparse';
import {parseTagged} from '../server/imports.ts';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const failedSaves=new Map();
let saveTimer=null,pendingDraft=null;
let me=null,page='dashboard',cache={},poll=null,ticker=null,attempt=null,qIndex=0,saveChain=Promise.resolve(),pending=0,saveFailed=false,recovery=null,renderVersion=0;
let sessionId=sessionStorage.getItem('cbt-device');if(!sessionId){sessionId=crypto.randomUUID();sessionStorage.setItem('cbt-device',sessionId);}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={dashboard:'Ringkasan',classes:'Kelas & rombel',subjects:'Mata pelajaran',students:'Data siswa',users:'Akun pengguna',banks:'Bank soal',questions:'Editor soal',exams:'Jadwal ujian',monitor:'Monitoring',tokens:'Token ujian',results:'Nilai & analisis',settings:'Pengaturan',available:'Ujian saya'};
const typeLabels={pilgan:'Pilihan ganda',kompleks:'Pilihan ganda kompleks',jodohkan:'Menjodohkan',benarsalah:'Benar / Salah',isian:'Isian singkat',uraian:'Uraian'};
const statuses={draft:'Draf',active:'Aktif',finished:'Berakhir',not_started:'Belum mulai',in_progress:'Mengerjakan',blocked:'Diblokir',submitted:'Selesai'};
const fmt=v=>v?new Date(v).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}):'—';
const badge=v=>`<span class="badge ${['blocked','finished'].includes(v)?'bad':['draft','not_started'].includes(v)?'warn':''}">${esc(statuses[v]??v)}</span>`;
const button=(label,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${esc(label)}</button>`;
const title=(name,desc='',actions='')=>`<div class="page-heading"><div><span class="eyebrow">Ruang asesmen / ${esc(me?.role??'')}</span><h1>${esc(name)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></div>`;
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('show'),4500);}
function showError(error,target){if(target){target.textContent=error.message;}else toast(error.message);}
async function api(path,body,method){await getUser();const r=await fetch('/api/'+path,{method:method??(body?'POST':'GET'),headers:{'Content-Type':'application/json','X-Exam-Session':sessionId},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw new Error('Server tidak merespons. Coba kembali.');}if(!r.ok)throw new Error(data.error??'Permintaan gagal.');return data;}
async function rows(resource,force=false){if(force||!cache[resource])cache[resource]=await api(resource);return cache[resource];}
const empty=(heading,description)=>`<div class="empty"><h2>${esc(heading)}</h2><p>${esc(description)}</p></div>`;
const table=(headers,body)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body.join('')}</tbody></table></div>`;
function openDialog(html){modal.innerHTML=html;modal.showModal();modal.querySelector('input,select,textarea,button')?.focus();}
const closeDialog=()=>modal.close();
const errorBox='<div class="error" role="alert"></div>';
const formActions=(label='Simpan')=>`<div class="dialog-actions">${button('Batal','close')}<button class="primary" type="submit">${label}</button></div>`;
function field(name,label,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(name,label,options,value='',multiple=false){return `<label>${esc(label)}<select name="${name}" ${multiple?'multiple size="4"':''} required>${multiple?'':'<option value="">Pilih…</option>'}${options.map(([v,l])=>`<option value="${esc(v)}" ${(Array.isArray(value)?value.map(String).includes(String(v)):String(v)===String(value))?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
const area=(name,label,value,extra='')=>`<label>${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const check=(name,label,value=true)=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}>${esc(label)}</label>`;
function formData(form){const d=Object.fromEntries(new FormData(form));for(const el of form.querySelectorAll('input[type=checkbox]'))d[el.name]=el.checked;for(const el of form.querySelectorAll('select[multiple]'))d[el.name]=[...el.selectedOptions].map(o=>Number(o.value));return d;}
async function submitForm(form,fn){const submit=form.querySelector('[type=submit]');submit.disabled=true;form.querySelector('.error').textContent='';try{await fn(formData(form));}catch(e){showError(e,form.querySelector('.error'));}finally{submit.disabled=false;}}
function navItems(){if(me.role==='siswa')return ['available'];if(me.role==='guru')return ['dashboard','banks','exams','results'];if(me.role==='operator')return ['dashboard','students','monitor','tokens'];return ['dashboard','classes','subjects','students','users','banks','exams','monitor','tokens','results','settings'];}
function shell(){app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">C</span><div>SMART EXAM<small>COMPUTER BASED TEST</small></div></div><nav>${navItems().map(n=>`<a href="#${n}" class="${page===n?'active':''}">${labels[n]}</a>`).join('')}</nav><footer><p>${esc(me.name)}<br><span class="muted">${esc(me.email)}</span></p>${button('Keluar','logout')}</footer></aside><div class="workspace"><header class="topbar"><span>${esc(me.settings.schoolName)} <span class="muted">/ ${esc(me.settings.academicYear??'')}</span></span><span class="badge">${esc(me.role.toUpperCase())}</span></header><main class="content" id="content"><div class="skeleton"></div></main></div></div>`;}
function authScreen(mode='login',message=''){
 clearInterval(poll);clearInterval(ticker);attempt=null;
 app.innerHTML=`<div class="auth"><aside class="auth-story"><div class="brand"><span class="brand-mark">C</span><div>SMART EXAM PRO<small>COMPUTER BASED TEST</small></div></div><div><span class="eyebrow">Ruang untuk bertumbuh</span><h1>Asesmen yang baik.<br><em>Potensi yang terlihat.</em></h1><p>Satu ruang untuk ujian, pemantauan, dan evaluasi belajar yang lebih terarah.</p></div><div class="orbit" aria-hidden="true"><span>CBT</span><i></i></div><small>SMART EXAM PRO &nbsp; / &nbsp; PORTAL AKADEMIK</small></aside><main class="auth-form"><section><span class="eyebrow">Selamat datang</span><h2>${mode==='login'?'Masuk ke ruang ujian':mode==='forgot'?'Pulihkan akses':'Atur kata sandi'}</h2><p class="muted">${mode==='login'?'Gunakan akun email yang terdaftar di sekolah.':mode==='forgot'?'Tautan pemulihan dikirim ke email akun Anda.':'Selesaikan pengaturan akun untuk melanjutkan.'}</p><form id="auth-form">${errorBox}${message?`<div class="help">${esc(message)}</div>`:''}${['login','forgot'].includes(mode)?field('email','Alamat email','','email','required autocomplete="username"'):''}${mode!=='forgot'?field('password','Kata sandi','','password','required '+(mode==='login'?'':'minlength="10" ')+'autocomplete="'+(mode==='login'?'current-password':'new-password')+'"'):''}<button class="primary" type="submit">${mode==='login'?'Masuk ke akun →':mode==='forgot'?'Kirim tautan pemulihan':'Simpan kata sandi'}</button></form>${mode==='login'?button('Lupa kata sandi?','forgot','','text-btn'):button('Kembali ke login','auth-login','','text-btn')}<div class="auth-note"><strong>Belum memiliki akses?</strong><br>Hubungi administrator sekolah untuk pendaftaran akun. Siswa, guru, dan operator menggunakan akun masing-masing.<details><summary>Panduan administrator pertama</summary>Undang akun melalui Identity di dashboard Netlify, terima undangan, lalu tambahkan peran <strong>admin</strong> pada akun tersebut. Selanjutnya, kelola akun dan data sekolah dari aplikasi.</details></div></section></main></div>`;
 document.querySelector('#auth-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async d=>{
  if(mode==='forgot'){await requestPasswordRecovery(d.email);authScreen('login','Periksa email Anda untuk tautan pemulihan.');return;}
  if(mode==='login')await login(d.email,d.password);
  else if(recovery?.type==='invite')await acceptInvite(recovery.token,d.password);
  else await updateUser({password:d.password});
  recovery=null;await loadSession();
 });};
}
async function loadSession(){
 cache={};me=await api('me');
 if(me.role==='siswa'&&me.profile)await api('claim',{});
 page=navItems().includes(location.hash.slice(1))?location.hash.slice(1):me.role==='siswa'?'available':'dashboard';await render();
}
async function render(){
 const version=++renderVersion;clearInterval(poll);clearInterval(ticker);attempt=null;shell();
 const content=document.querySelector('#content');
 try{
  if(me.role==='siswa'&&!me.profile){content.innerHTML=title('Akun belum terhubung')+`<div class="panel">${empty('Pendaftaran siswa diperlukan','Administrator perlu menambahkan email Anda ke Data siswa. Keluar lalu masuk kembali setelah data tersimpan.')}</div>`;return;}
  let html='';
  if(page==='dashboard')html=await dashboard();
  else if(['classes','subjects','students','banks','exams','users'].includes(page))html=await resourcePage(page);
  else if(page==='settings')html=settingsPage();
  else if(page==='available')html=await availablePage();
  else if(['tokens','monitor','results'].includes(page))html=await examPickerPage(page);
  if(version!==renderVersion)return;
  content.innerHTML=html;
  if(['tokens','monitor','results'].includes(page)){const picker=document.querySelector('#exam-picker');if(picker?.value)await loadExamPanel(picker.value);picker?.addEventListener('change',()=>loadExamPanel(picker.value));}
  if(page==='settings')document.querySelector('#settings-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async d=>{me.settings=await api('settings',d,'PUT');toast('Pengaturan tersimpan.');});};
 }catch(e){if(version===renderVersion)content.innerHTML=title('Halaman belum tersedia')+`<div class="panel"><p class="error">${esc(e.message)}</p>${button('Coba kembali','refresh')}</div>`;}
}
async function dashboard(){
 const resources=me.role==='operator'?['students','exams']:me.role==='guru'?['classes','banks','exams']:['classes','students','banks','exams'];
 await Promise.all(resources.map(r=>rows(r)));
 const exams=cache.exams??[];const active=exams.filter(e=>e.status==='active').length;
 const summary=me.role==='guru'?[['Bank soal',cache.banks.length],['Jadwal ujian',exams.length],['Ujian aktif',active],['Kelas tersedia',cache.classes.length]]:me.role==='operator'?[['Peserta terdaftar',cache.students.length],['Jadwal ujian',exams.length],['Ujian aktif',active],['Sesi terjadwal',new Set(exams.map(e=>e.sessionName)).size]]:[['Kelas & rombel',cache.classes.length],['Peserta terdaftar',cache.students.length],['Bank soal',cache.banks.length],['Ujian aktif',active]];
 return title('Ruang kendali asesmen','Kelola persiapan, pantau pelaksanaan, dan baca hasil belajar.')+`<section class="welcome"><div><span class="eyebrow">${esc(me.settings.semester??'Semester')} · ${esc(me.settings.academicYear??'')}</span><h2>Setiap ujian dimulai<br>dari persiapan yang baik.</h2><p>${exams.length?'Tinjau jadwal, pastikan peserta siap, dan kelola ujian dari satu tempat.':'Mulai dengan data kelas dan mata pelajaran, lalu susun bank soal dan jadwal ujian pertama.'}</p><a href="#${me.role==='operator'?'monitor':'exams'}">${me.role==='operator'?'Buka monitoring':'Kelola jadwal ujian'} →</a></div><div class="stamp"><strong>${String(active).padStart(2,'0')}</strong><span>UJIAN AKTIF</span></div></section><div class="stats">${summary.map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><section class="panel"><div class="panel-title"><h2>Agenda ujian</h2><a href="#exams" class="muted">Lihat semua →</a></div>${exams.length?table(['Ujian','Sesi / ruang','Mulai','Status'],exams.slice(0,8).map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${esc(e.sessionName)} / ${esc(e.room)}</td><td>${fmt(e.startTime)}</td><td>${badge(e.status)}</td></tr>`)):empty('Belum ada jadwal','Jadwal yang Anda buat muncul di sini. Tidak ada data contoh yang memengaruhi hasil ujian.')}</section>`;
}
const resourceColumns={classes:['Nama kelas','Tingkat','Jurusan'],subjects:['Kode','Mata pelajaran'],students:['Nama siswa','NISN / peserta','Kelas','Email'],banks:['Kode / judul','Mata pelajaran','KKM','Status'],exams:['Judul','Mulai / selesai','Durasi','Status'],users:['Nama / email','Peran']};
async function resourcePage(resource){
 const deps={students:['classes'],banks:['subjects'],exams:['banks','classes'],classes:[],subjects:[],users:[]};
 // Operators only need the read-only student roster, and do not have access to question banks.
 await Promise.all([rows(resource,true),...(resource==='exams'&&me.role==='operator'?[]:deps[resource]).map(r=>rows(r))]);
 const data=cache[resource],editable=me.role!=='operator';
 const actions=(editable?button('＋ Tambah '+({classes:'kelas',subjects:'mapel',students:'siswa',banks:'bank soal',exams:'ujian',users:'akun'}[resource]),'edit',`data-resource="${resource}"`,'primary'):'')+(['students','banks'].includes(resource)&&editable?button(resource==='students'?'Impor CSV':'Panduan soal','import',`data-resource="${resource}"`):'')+(resource==='students'?button('Cetak kartu','cards'):'');
 return title(labels[resource],{students:'Email siswa harus sama dengan akun Identity yang dibuat administrator.',users:'Buat akun email dan tetapkan hak akses. Data siswa dikelola terpisah.',banks:'Enam tipe soal, bobot penilaian, dan kunci jawaban dalam satu bank.',exams:'Jadwalkan ujian, tentukan kelas, dan atur perilaku pengerjaan.'}[resource]??'Kelola data akademik sekolah.',actions)+`<section class="panel"><div class="filters"><input type="search" id="table-search" placeholder="Cari ${esc(labels[resource].toLowerCase())}…" aria-label="Cari data"><span class="muted">${data.length} data</span></div>${data.length?table([...resourceColumns[resource],'Tindakan'],data.map(r=>{
  let cells=[];
  if(resource==='classes')cells=[esc(r.name),esc(r.level),esc(r.major)];
  if(resource==='subjects')cells=[esc(r.code),esc(r.name)];
  if(resource==='students')cells=[`<strong>${esc(r.fullName)}</strong>${r.loggedIn?' <span class="badge">Login</span>':''}`,`${esc(r.nisn)}<br><small>${esc(r.examNumber)}</small>`,esc(cache.classes?.find(c=>c.id===r.classId)?.name??r.classId),esc(r.email)];
  if(resource==='banks')cells=[`<small>${esc(r.code)}</small><br><strong>${esc(r.title)}</strong>`,esc(cache.subjects?.find(s=>s.id===r.subjectId)?.name??r.subjectId),r.kkm,badge(r.status)];
  if(resource==='exams')cells=[`<strong>${esc(r.title)}</strong><br><small>${esc(r.sessionName)} / ${esc(r.room)}</small>`,`${fmt(r.startTime)}<br><small class="muted">${fmt(r.endTime)}</small>`,`${r.duration} menit`,badge(r.status)];
  if(resource==='users')cells=[`${esc(r.name??'')}<br><small>${esc(r.email)}</small>`,esc(r.roles.length?r.roles.join(', '):'siswa')];
  const extra=resource==='banks'?button('Soal','questions',`data-id="${r.id}"`,'small'):'';
  const edit=editable?button('Ubah','edit',`data-resource="${resource}" data-id="${r.id}"`,'small')+button('Hapus','delete',`data-resource="${resource}" data-id="${r.id}"`,'small danger'):'';
  return `<tr>${cells.map(c=>`<td>${c}</td>`).join('')}<td><div class="actions">${extra}${edit||'—'}</div></td></tr>`;
 })):empty('Data belum ditambahkan','Tambahkan data pertama melalui tombol di atas.')}</section>`;
}
async function editResource(resource,recordId){
 const r=cache[resource]?.find(r=>String(r.id)===String(recordId))??{};let fields='';
 if(resource==='classes')fields=field('name','Nama kelas',r.name??'','text','required')+field('level','Tingkat',r.level??'','text','required')+field('major','Jurusan',r.major??'Umum');
 if(resource==='subjects')fields=field('code','Kode',r.code??'','text','required')+field('name','Mata pelajaran',r.name??'','text','required');
 if(resource==='students')fields=field('fullName','Nama lengkap',r.fullName??'','text','required')+field('nisn','NISN (pertahankan awalan nol)',r.nisn??'','text','required')+field('examNumber','Nomor peserta',r.examNumber??'','text','required')+field('email','Email akun',r.email??'','email','required')+select('classId','Kelas',(cache.classes??[]).map(c=>[c.id,c.name]),r.classId)+select('gender','Jenis kelamin',[['L','Laki-laki'],['P','Perempuan']],r.gender??'L');
 if(resource==='banks')fields=field('code','Kode bank',r.code??'','text','required')+field('title','Judul bank soal',r.title??'','text','required')+select('subjectId','Mata pelajaran',(cache.subjects??[]).map(s=>[s.id,s.name]),r.subjectId)+field('classLevel','Tingkat',r.classLevel??'Semua')+field('kkm','KKM',r.kkm??75,'number','min="0" max="100" required')+select('status','Status',[['draft','Draf'],['active','Aktif']],r.status??'draft')+`<div class="wide help">Komposisi opsional: kosongkan dengan {} untuk memakai semua soal. Contoh: {"pilgan":{"count":10,"weight":2},"uraian":{"count":2,"weight":5}}. Bobot di sini menggantikan bobot soal pada saat ujian dimulai.</div><div class="wide">${area('composition','Komposisi JSON',JSON.stringify(r.composition??{},null,2))}</div>`;
 if(resource==='users')fields=(r.id?`<div class="wide help">${esc(r.email)} — kosongkan kata sandi jika tidak diubah.</div>`:field('name','Nama lengkap','','text','required')+field('email','Email','','email','required'))+field('password','Kata sandi','','password',`${r.id?'':'required'} minlength="10" autocomplete="new-password"`)+select('role','Peran',[['siswa','Siswa'],['guru','Guru'],['operator','Operator'],['admin','Admin']],r.roles?.[0]??'siswa');
 if(resource==='exams'){
  const local=v=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
  fields=field('title','Judul ujian',r.title??'','text','required')+select('bankId','Bank soal',(cache.banks??[]).map(b=>[b.id,b.title]),r.bankId)+select('classIds','Kelas peserta (Ctrl/⌘ untuk beberapa)',(cache.classes??[]).map(c=>[c.id,c.name]),r.classIds??[],true)+field('duration','Durasi (menit)',r.duration??60,'number','required min="1" max="1440"')+field('startTime','Mulai (waktu lokal)',local(r.startTime),'datetime-local','required')+field('endTime','Selesai (waktu lokal)',local(r.endTime),'datetime-local','required')+field('sessionName','Sesi',r.sessionName??'Sesi 1','text','required')+field('room','Ruang',r.room??'Ruang 01','text','required')+select('status','Status',[['draft','Draf'],['active','Aktif'],['finished','Berakhir']],r.status??'draft')+check('randomizeQuestions','Acak urutan soal',r.randomizeQuestions??true)+check('randomizeOptions','Acak opsi jawaban',r.randomizeOptions??true)+check('showResults','Tampilkan hasil setelah selesai',r.showResults??false)+check('antiCheat','Pantau perpindahan tab',r.antiCheat??true);
 }
 openDialog(`<h2>${r.id?'Ubah':'Tambah'} ${esc(labels[resource])}</h2><form id="edit-form">${errorBox}<div class="form-grid">${fields}</div>${formActions()}</form>`);
 document.querySelector('#edit-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async d=>{
  if(resource==='banks')d.composition=JSON.parse(d.composition);
  if(resource==='exams'){d.startTime=new Date(d.startTime).toISOString();d.endTime=new Date(d.endTime).toISOString();}
  await api(resource,{...d,...(r.id?{id:r.id}:{})},r.id?'PUT':'POST');cache[resource]=null;closeDialog();toast('Data tersimpan.');await render();
 });};
}
async function deleteResource(resource,recordId){
 openDialog(`<h2>Hapus data?</h2><p>Data yang masih digunakan oleh ujian atau peserta tidak dapat dihapus.</p><form id="delete-form">${errorBox}${formActions('Hapus data')}</form>`);
 document.querySelector('#delete-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async()=>{await api(resource,{id:recordId,role:'siswa'},'DELETE');cache[resource]=null;closeDialog();toast('Data dihapus.');await render();});};
}
const examples={pilgan:{options:{A:'Pilihan pertama',B:'Pilihan kedua',C:'Pilihan ketiga',D:'Pilihan keempat'},correctAnswer:'A'},kompleks:{options:{A:'Pernyataan pertama',B:'Pernyataan kedua',C:'Pernyataan ketiga'},correctAnswer:['A','C']},jodohkan:{options:{premises:{p1:'Premis pertama',p2:'Premis kedua'},targets:{t1:'Target pertama',t2:'Target kedua'}},correctAnswer:{p1:'t2',p2:'t1'}},benarsalah:{options:{statements:{s1:'Pernyataan pertama',s2:'Pernyataan kedua'}},correctAnswer:{s1:'B',s2:'S'}},isian:{options:{case_sensitive:false},correctAnswer:['alternatif jawaban','jawaban lain']},uraian:{options:{},correctAnswer:'Rubrik penilaian guru'}};
async function questionsPage(bankId){
 clearInterval(poll);clearInterval(ticker);page='banks';const data=await api('questions?bankId='+bankId);cache.questions=data;cache.bankId=bankId;
 document.querySelector('#content').innerHTML=title('Editor bank soal',cache.banks?.find(b=>b.id===Number(bankId))?.title??'',button('← Bank soal','refresh')+button('Impor soal','import-questions',`data-id="${bankId}"`)+button('＋ Tambah soal','question-edit',`data-bank="${bankId}"`,'primary'))+`<section class="panel">${data.length?table(['No.','Tipe','Teks soal','Bobot','Tindakan'],data.map(q=>`<tr><td>${q.number}</td><td>${esc(typeLabels[q.type])}</td><td>${esc(q.text.slice(0,140))}</td><td>${q.weight}</td><td><div class="actions">${button('Ubah','question-edit',`data-bank="${bankId}" data-id="${q.id}"`,'small')}${button('Hapus','question-delete',`data-id="${q.id}"`,'small danger')}</div></td></tr>`)):empty('Belum ada soal','Tambahkan soal satu per satu atau impor kumpulan soal.')}</section>`;
}
function questionEdit(bankId,recordId){
 const q=cache.questions.find(q=>q.id===Number(recordId))??{type:'pilgan',weight:1,number:cache.questions.length+1,...examples.pilgan};
 openDialog(`<h2>${recordId?'Ubah':'Tambah'} soal</h2><form id="question-form">${errorBox}<div class="form-grid">${field('number','Nomor',q.number,'number','min="1" required')}${select('type','Tipe soal',Object.entries(typeLabels),q.type)}<div class="wide">${area('text','Pertanyaan (teks biasa)',q.text??'','required')}</div>${field('weight','Bobot',q.weight,'number','min="0.01" step="0.01" required')}${field('image','URL gambar (opsional)',q.image??'','url')}<div class="wide help">Opsi dan kunci menggunakan JSON. Pilih tipe untuk melihat struktur contoh. Teks biasa ditampilkan dengan aman kepada peserta.</div><div class="wide">${area('options','Opsi JSON',JSON.stringify(q.options,null,2),'required')}</div><div class="wide">${area('correctAnswer','Kunci / rubrik JSON',JSON.stringify(q.correctAnswer,null,2),'required')}</div><div class="wide">${area('explanation','Pembahasan (guru)',q.explanation??'')}</div></div>${formActions()}</form>`);
 const form=document.querySelector('#question-form');form.elements.type.onchange=()=>{const ex=examples[form.elements.type.value];form.elements.options.value=JSON.stringify(ex.options,null,2);form.elements.correctAnswer.value=JSON.stringify(ex.correctAnswer,null,2);};
 form.onsubmit=e=>{e.preventDefault();submitForm(form,async d=>{d.options=JSON.parse(d.options);d.correctAnswer=JSON.parse(d.correctAnswer);await api('questions',{...d,bankId:Number(bankId),...(recordId?{id:Number(recordId)}:{})},recordId?'PUT':'POST');closeDialog();toast('Soal tersimpan.');await questionsPage(bankId);});};
}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importStudents(){
 openDialog(`<h2>Impor data siswa</h2><p class="muted">CSV berkolom email, nisn, examNumber, fullName, classId, gender. NISN disimpan sebagai teks. Baris dengan NISN yang sama diperbarui. Akun login dibuat terpisah di Akun pengguna.</p>${button('Unduh template CSV','student-template')}<form id="import-form">${errorBox}<label>Berkas CSV<input name="file" type="file" accept=".csv,text/csv" required></label>${formActions('Impor siswa')}</form>`);
 document.querySelector('#import-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;submitForm(form,async()=>{const parsed=Papa.parse(await form.elements.file.files[0].text(),{header:true,skipEmptyLines:true});if(parsed.errors.length)throw new Error('Format CSV tidak valid: '+parsed.errors[0].message);await api('import-students',{students:parsed.data});cache.students=null;closeDialog();toast('Data siswa diimpor.');await render();});};
}
function importQuestions(bankId){
 openDialog(`<h2>Impor soal</h2><p class="muted">Pilih JSON, teks bertanda, atau Word .docx. Dokumen .doc perlu disimpan ulang menjadi .docx. Maksimal 500 soal / 2 MB.</p><div class="actions">${button('Template 6 tipe (JSON)','question-template')}${button('Template teks / Word','word-template')}</div><form id="import-form">${errorBox}<label>Berkas soal<input name="file" type="file" accept=".json,.txt,.docx" required></label>${formActions('Impor soal')}</form>`);
 document.querySelector('#import-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;submitForm(form,async()=>{
  const file=form.elements.file.files[0];if(file.size>2000000)throw new Error('Berkas maksimal 2 MB.');let data;
  if(file.name.endsWith('.json')){const parsed=JSON.parse(await file.text());data=Array.isArray(parsed)?parsed:parsed.questions;}
  else{let text;if(file.name.endsWith('.docx')){const mammoth=await import('mammoth/mammoth.browser.js');text=(await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()})).value;}else text=await file.text();data=parseTagged(text);}
  await api('import-questions',{bankId:Number(bankId),questions:data});closeDialog();toast('Soal berhasil diimpor.');await questionsPage(bankId);
 });};
}
function settingsPage(){return title('Pengaturan sekolah','Identitas akademik dan aturan pelaksanaan ujian.')+`<section class="panel"><form id="settings-form">${errorBox}<div class="form-grid">${field('schoolName','Nama sekolah',me.settings.schoolName,'text','required')}${field('academicYear','Tahun ajaran',me.settings.academicYear??'2026/2027','text','required')}${select('semester','Semester',[['Ganjil','Ganjil'],['Genap','Genap']],me.settings.semester??'Ganjil')}${field('maxViolations','Blokir setelah pelanggaran',me.settings.maxViolations??3,'number','min="1" max="100" required')}</div><div class="help" style="margin-top:20px">Pemantauan tab membantu operator mencatat aktivitas. Pengawasan ruang ujian tetap diperlukan.</div><button type="submit" class="primary">Simpan pengaturan</button></form></section>`;}
async function availablePage(){const data=await api('available');cache.available=data;return title('Ujian saya','Periksa jadwal dan siapkan token dari operator sebelum memulai.',button('Perbarui','refresh'))+`<div class="exam-grid">${data.length?data.map(e=>`<article class="exam-card"><div class="actions">${badge(e.participation?.status??e.status)}<span class="eyebrow">${esc(e.sessionName)}</span></div><h2>${esc(e.title)}</h2><dl><div><dt>Waktu mulai</dt><dd>${fmt(e.startTime)}</dd></div><div><dt>Batas jadwal</dt><dd>${fmt(e.endTime)}</dd></div><div><dt>Durasi</dt><dd>${e.duration} menit</dd></div><div><dt>Ruang</dt><dd>${esc(e.room)}</dd></div></dl>${e.participation?.status==='submitted'?`<p>${e.participation.score!=null?'Nilai: <strong>'+e.participation.score+'</strong>':'Hasil disimpan. Nilai dirilis oleh sekolah.'}${e.participation.graded?'':'<br><small>Menunggu koreksi guru.</small>'}</p>`:`<div class="actions">${button(e.participation?.status==='in_progress'?'Lanjutkan ujian':e.participation?.status==='blocked'?'Periksa status':'Masuk ruang ujian','enter',`data-id="${e.id}"`,'primary')}</div>`}</article>`).join(''):`<section class="panel">${empty('Belum ada ujian untuk kelas Anda','Ujian muncul setelah diaktifkan oleh sekolah. Perbarui halaman untuk memeriksa jadwal terbaru.')}</section>`}</div>`;}
async function examPickerPage(kind){await rows('exams',true);return title(labels[kind],{tokens:'Rilis token untuk peserta pada sesi yang dipilih.',monitor:'Status peserta diperbarui otomatis setiap empat detik.',results:'Rekap nilai, koreksi uraian, dan analisis butir soal.'}[kind],button('Perbarui','refresh'))+`<div class="filters"><select id="exam-picker" aria-label="Pilih ujian"><option value="">Pilih jadwal ujian…</option>${cache.exams.map(e=>`<option value="${e.id}" ${String(cache.examSelection)===String(e.id)?'selected':''}>${esc(e.title)} · ${esc(e.sessionName)}</option>`).join('')}</select></div><div id="exam-panel">${empty('Pilih ujian','Data untuk jadwal yang dipilih ditampilkan di sini.')}</div>`;}
async function loadExamPanel(examId){
 clearInterval(poll);cache.examSelection=examId;const target=document.querySelector('#exam-panel');if(!examId){target.innerHTML=empty('Pilih ujian','Pilih jadwal untuk melanjutkan.');return;}
 const kind=page;target.innerHTML='<div class="skeleton"></div>';
 try{
  if(kind==='tokens'){const e=cache.exams.find(e=>e.id===Number(examId));target.innerHTML=`<section class="panel"><span class="eyebrow">${esc(e.sessionName)} · ${esc(e.room)}</span><h2>${esc(e.title)}</h2><div class="token">${esc(e.tokenActive&&new Date(e.tokenExpires)>new Date()?e.token:'BELUM RILIS')}</div><p class="muted">Berlaku sampai ${fmt(e.tokenExpires)}. Tampilkan token kepada peserta di ruang ujian.</p><form id="token-form">${errorBox}<div class="filters">${field('minutes','Masa berlaku (menit)',60,'number','min="1" max="1440" required')}<button type="submit" class="primary">Buat & rilis token</button>${button('Nonaktifkan token','disable-token',`data-id="${examId}"`)}</div></form></section>`;document.querySelector('#token-form').onsubmit=ev=>{ev.preventDefault();submitForm(ev.currentTarget,async d=>{await api('token',{...d,examId:Number(examId)});cache.exams=null;await rows('exams');await loadExamPanel(examId);toast('Token baru dirilis.');});};}
  if(kind==='monitor'){await updateMonitor(examId);poll=setInterval(()=>updateMonitor(examId).catch(e=>toast(e.message)),4000);}
  if(kind==='results'){const data=await api('results?examId='+examId);if(page!==kind||String(cache.examSelection)!==String(examId))return;cache.results=data;target.innerHTML=resultsHtml(data);}
 }catch(e){target.innerHTML=`<p class="error">${esc(e.message)}</p>`;}
}
async function updateMonitor(examId){const data=await api('monitor?examId='+examId);if(page!=='monitor'||cache.examSelection!==examId)return;document.querySelector('#exam-panel').innerHTML=`<div class="stats">${[['Peserta',data.length],['Mengerjakan',data.filter(p=>p.status==='in_progress').length],['Selesai',data.filter(p=>p.status==='submitted').length],['Diblokir',data.filter(p=>p.status==='blocked').length]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><section class="panel">${data.length?table(['Peserta','Status','Jawaban','Sisa waktu','Pelanggaran','Kontrol'],data.map(p=>`<tr><td><strong>${esc(p.fullName)}</strong><br><small>${esc(p.examNumber)}</small></td><td>${badge(p.status)}</td><td>${p.answered} / ${p.total}</td><td>${p.status==='submitted'?'—':remaining(p.deadline)}</td><td>${p.violations}</td><td><div class="actions">${button('Reset login','control',`data-kind="reset" data-student="${p.studentId}"`,'small')}${p.id&&p.status!=='submitted'?button('+ Waktu','control',`data-kind="extend" data-id="${p.id}"`,'small')+button('Buka blokir','control',`data-kind="unblock" data-id="${p.id}"`,'small')+button('Selesaikan','control',`data-kind="submit" data-id="${p.id}"`,'small danger'):''}</div></td></tr>`)):empty('Belum ada peserta','Tambahkan siswa ke kelas yang mengikuti ujian.')}</section>`;}
function remaining(deadline){if(!deadline)return '—';const seconds=Math.max(0,Math.ceil((new Date(deadline)-Date.now())/1000));return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function resultsHtml(d){const ps=d.participants;const avg=ps.length?(ps.reduce((n,p)=>n+p.score,0)/ps.length).toFixed(2):'—';return `<div class="stats">${[['Selesai',ps.length],['Rata-rata',avg],['KKM',d.kkm],['Tuntas',ps.filter(p=>p.graded&&p.passed).length]].map(([l,v])=>`<div class="stat"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><section class="panel"><div class="panel-title"><h2>Rekapitulasi nilai</h2><div class="actions">${button('Ekspor CSV','export-results')}${button('Cetak','print')}</div></div>${ps.length?table(['Peserta','Nomor peserta','Nilai / 100','Koreksi','Ketuntasan'],ps.map(p=>`<tr><td>${esc(p.student)}</td><td>${esc(p.examNumber)}</td><td><strong>${p.score}</strong></td><td>${p.graded?'Lengkap':'Menunggu uraian'}</td><td>${p.graded?(p.passed?'Tuntas':'Remedial'):'Sementara'}</td></tr>`)):empty('Belum ada hasil','Hasil muncul setelah peserta menyerahkan ujian.')}</section><section class="panel"><h2>Koreksi uraian</h2>${d.essays.length?d.essays.map(a=>`<div class="summary-row"><div><strong>${esc(a.student)}</strong><p>${esc(a.text.slice(0,120))}</p><small>${a.correct===null?'Belum dikoreksi':a.awarded+' / '+a.weight}</small></div>${button('Koreksi','grade',`data-id="${a.id}"`)}</div>`).join(''):empty('Tidak ada uraian','Jawaban uraian yang sudah diserahkan muncul di sini.')}</section><section class="panel"><h2>Analisis butir soal</h2><p class="muted">P = proporsi jawaban benar. D = selisih kelompok atas dan bawah. D memerlukan minimal dua peserta. Nilai uraian mengikuti hasil koreksi.</p>${d.analysis.length?table(['No.','Tipe','Kesukaran (P)','Kategori','Daya pembeda (D)','Distribusi pilihan'],d.analysis.map(q=>`<tr><td>${q.number}</td><td>${esc(typeLabels[q.type])}</td><td>${q.p?.toFixed(2)??'—'}</td><td>${q.category}</td><td>${q.d?.toFixed(2)??'—'}</td><td>${esc(JSON.stringify(q.distribution))}</td></tr>`)):empty('Data belum cukup','Analisis tersedia setelah peserta menyelesaikan ujian.')}</section>`;}
function gradeDialog(answerId){const a=cache.results.essays.find(a=>a.id===Number(answerId));openDialog(`<h2>Koreksi uraian</h2><p><strong>${esc(a.student)}</strong></p><p>${esc(a.text)}</p><div class="help">Rubrik: ${esc(typeof a.rubric==='string'?a.rubric:JSON.stringify(a.rubric))}</div><div class="essay">${esc(a.answer??'(Tidak dijawab)')}</div><form id="grade-form">${errorBox}${field('awarded',`Skor (maksimal ${a.weight})`,a.awarded,'number',`required min="0" max="${a.weight}" step="0.01"`)}${area('feedback','Catatan untuk peserta',a.feedback??'')}${formActions('Simpan koreksi')}</form>`);document.querySelector('#grade-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async d=>{await api('grade',{...d,id:a.id});closeDialog();toast('Koreksi tersimpan.');await loadExamPanel(cache.examSelection);});};}
async function enterExam(examId){const e=cache.available.find(e=>e.id===Number(examId));if(e.participation?.status==='blocked'){toast('Ujian diblokir. Hubungi operator untuk membuka blokir.');return;}if(e.participation){const p=await api('start',{examId:Number(examId)});await openAttempt(p.id);return;}
 openDialog(`<h2>Konfirmasi peserta</h2><div class="help"><strong>${esc(me.profile.fullName)}</strong><br>NISN ${esc(me.profile.nisn)} · ${esc(me.profile.examNumber)}</div><p>${esc(e.title)} — ${e.duration} menit. Waktu dimulai ketika Anda menekan tombol mulai. ${e.antiCheat?'Perpindahan tab dicatat dan dapat memblokir ujian.':''}</p><form id="start-form">${errorBox}${field('token','Token dari operator','','text','required maxlength="10" autocomplete="off"')}${formActions('Mulai ujian')}</form>`);
 document.querySelector('#start-form').onsubmit=ev=>{ev.preventDefault();submitForm(ev.currentTarget,async d=>{const p=await api('start',{examId:Number(examId),token:d.token});closeDialog();await openAttempt(p.id);});};
}
async function openAttempt(pid){clearInterval(poll);clearInterval(ticker);qIndex=0;attempt=await api('attempt?id='+pid);saveFailed=false;failedSaves.clear();showAttempt();if(attempt.status==='in_progress'){
 ticker=setInterval(()=>{const node=document.querySelector('#exam-timer');if(node)node.textContent=remaining(attempt.deadline);if(new Date(attempt.deadline)<=new Date()){clearInterval(ticker);submitAttempt(true).catch(e=>{toast(e.message);poll=setInterval(()=>syncAttempt(),10000);});}},1000);
 poll=setInterval(()=>syncAttempt(),10000);
 }}
async function syncAttempt(){if(!attempt)return;try{const fresh=await api('attempt?id='+attempt.id);if(!attempt||fresh.id!==attempt.id)return;attempt.deadline=fresh.deadline;attempt.violations=fresh.violations;if(fresh.status!==attempt.status){attempt=fresh;showAttempt();}}catch(e){toast(e.message);}}
function showAttempt(){
 const content=document.querySelector('#content');
 if(attempt.status!=='in_progress'){clearInterval(poll);clearInterval(ticker);content.innerHTML=title(attempt.status==='submitted'?'Ujian telah selesai':'Ujian diblokir')+`<section class="panel">${empty(attempt.status==='submitted'?'Jawaban Anda sudah disimpan':'Hubungi operator ujian',attempt.status==='submitted'?(attempt.score!=null?'Nilai: '+attempt.score+(attempt.graded?'':' · Menunggu koreksi guru'):'Hasil tersimpan. Nilai dirilis oleh sekolah.'):'Operator dapat memeriksa catatan pelanggaran dan membuka akses Anda.')}<div class="actions">${button('Kembali ke ujian saya','refresh')}${attempt.status==='blocked'?button('Periksa status','sync-attempt'):''}</div></section>`;return;}
 const q=attempt.questions[qIndex];if(!q)return;const a=attempt.answers.find(a=>a.questionId===q.id)??{answer:null,doubtful:false};
 content.innerHTML=title(attempt.title,`Peserta: ${me.profile.fullName} · ${me.profile.examNumber}`)+`<div class="exam-layout"><section class="panel"><div class="panel-title"><span class="eyebrow">Soal ${qIndex+1} dari ${attempt.questions.length}</span><div class="actions"><span class="badge">${esc(typeLabels[q.type])}</span>${button('A−','font-small','','small')}${button('A＋','font-large','','small')}</div></div><div class="question-text">${esc(q.text)}</div>${q.image&&/^https?:\/\//.test(q.image)?`<img class="question-image" src="${esc(q.image)}" alt="Gambar soal" referrerpolicy="no-referrer">`:''}<div id="answer-input">${answerInput(q,a.answer)}</div><div class="save-state" id="save-state" aria-live="polite">${pending?'Menyimpan jawaban…':saveFailed?'Gagal menyimpan. Coba simpan kembali.':'Jawaban tersinkron dengan server.'}</div><div class="error" id="save-error"></div><div class="summary-row">${check('doubtful','Ragu-ragu',a.doubtful)}${button('Simpan kembali','retry-save','','small')}</div><div class="actions">${qIndex>0?button('← Sebelumnya','prev-question'):''}${qIndex<attempt.questions.length-1?button('Selanjutnya →','next-question','','primary'):button('Selesai & kumpulkan','submit-attempt','','primary')}</div></section><aside><section class="panel"><div><span class="eyebrow">Sisa waktu</span><div id="exam-timer" class="timer">${remaining(attempt.deadline)}</div><small class="muted">Waktu mengikuti server</small></div><div><div class="question-map">${attempt.questions.map((q,i)=>{const a=attempt.answers.find(a=>a.questionId===q.id);return `<button data-action="jump-question" data-index="${i}" class="${i===qIndex?'current':''} ${a?.answer!=null&&a.answer!==''?'answered':''} ${a?.doubtful?'doubtful':''}">${i+1}</button>`;}).join('')}</div><p class="muted" style="font-size:11px">Hijau: terjawab · Kuning: ragu-ragu<br>Perpindahan tab: ${attempt.violations}</p>${button('Kumpulkan ujian','submit-attempt','','primary')}</div></section></aside></div>`;
 const input=document.querySelector('#answer-input');input.addEventListener('change',()=>collectAnswer());input.addEventListener('input',e=>{if(e.target.matches('textarea,input[type=text]'))collectAnswer();});document.querySelector('[name=doubtful]').onchange=()=>collectAnswer();
}
function answerInput(q,value){
 if(['pilgan','kompleks'].includes(q.type))return Object.entries(q.options).map(([key,label])=>`<label class="option"><input type="${q.type==='pilgan'?'radio':'checkbox'}" name="answer" value="${esc(key)}" ${(q.type==='pilgan'?value===key:Array.isArray(value)&&value.includes(key))?'checked':''}><span><strong>${esc(key)}.</strong> ${esc(label)}</span></label>`).join('');
 if(q.type==='isian')return field('answer','Jawaban Anda',value??'','text','autocomplete="off" maxlength="10000"');
 if(q.type==='uraian')return area('answer','Jawaban Anda',value??'','maxlength="28000"');
 if(q.type==='benarsalah')return Object.entries(q.options.statements??q.options).map(([k,label])=>`<div class="summary-row"><span>${esc(label)}</span><div class="actions">${['B','S'].map(v=>`<label class="check"><input type="radio" name="${esc(k)}" value="${v}" ${value?.[k]===v?'checked':''}>${v==='B'?'Benar':'Salah'}</label>`).join('')}</div></div>`).join('');
 if(q.type==='jodohkan')return Object.entries(q.options.premises??{}).map(([k,label])=>select(k,label,Object.entries(q.options.targets??{}),value?.[k]??'')).join('<br>');
 return '';
}
function collectAnswer(){
 if(!attempt||attempt.status!=='in_progress')return;
 const q=attempt.questions[qIndex],node=document.querySelector('#answer-input');let answer;
 if(q.type==='pilgan')answer=node.querySelector('input:checked')?.value??null;
 if(q.type==='kompleks')answer=[...node.querySelectorAll('input:checked')].map(el=>el.value);
 if(['isian','uraian'].includes(q.type))answer=node.querySelector('input,textarea').value;
 if(['jodohkan','benarsalah'].includes(q.type))answer=Object.fromEntries([...node.querySelectorAll('select,input:checked')].filter(el=>el.value).map(el=>[el.name,el.value]));
 const a={questionId:q.id,answer,doubtful:document.querySelector('[name=doubtful]').checked};const idx=attempt.answers.findIndex(a=>a.questionId===q.id);if(idx<0)attempt.answers.push(a);else attempt.answers[idx]=a;
 clearTimeout(saveTimer);pendingDraft=structuredClone(a);setSaveState('Menunggu penyimpanan…');
 saveTimer=setTimeout(()=>flushDraft(),400);
}
function flushDraft(){if(pendingDraft){clearTimeout(saveTimer);const draft=pendingDraft;pendingDraft=null;queueSave(draft);}}
function queueSave(a){
 const pid=attempt.id,data=structuredClone(a);pending++;setSaveState('Menyimpan jawaban…');
 saveChain=saveChain.then(async()=>{try{const response=await api('attempt',{id:pid,action:'save',...data});if(response.status==='submitted'&&attempt?.id===pid)await syncAttempt();failedSaves.delete(data.questionId);saveFailed=failedSaves.size>0;}catch(e){failedSaves.set(data.questionId,data);saveFailed=true;const node=document.querySelector('#save-error');if(node)node.textContent=e.message;throw e;}finally{pending--;if(!pending)setSaveState(saveFailed?'Jawaban belum tersimpan. Tekan Simpan kembali.':'Jawaban tersimpan.');}}).catch(()=>{});
}
function setSaveState(text){const node=document.querySelector('#save-state');if(node)node.textContent=text;}
async function submitAttempt(automatic=false){
 if(!attempt)return;
 if(!automatic){const unanswered=attempt.questions.length-attempt.answers.filter(a=>a.answer!=null&&a.answer!==''&&JSON.stringify(a.answer)!=='[]'&&JSON.stringify(a.answer)!=='{}').length;const doubtful=attempt.answers.filter(a=>a.doubtful).length;
  openDialog(`<h2>Kumpulkan ujian?</h2><p>${unanswered} soal belum dijawab dan ${doubtful} soal ditandai ragu-ragu. Jawaban tidak dapat diubah setelah dikumpulkan.</p><form id="submit-form">${errorBox}${formActions('Kumpulkan sekarang')}</form>`);document.querySelector('#submit-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async()=>{await finalizeAttempt();closeDialog();});};return;
 }
 await finalizeAttempt();
}
async function finalizeAttempt(){
 flushDraft();await saveChain;if(saveFailed)throw new Error('Ada jawaban belum tersimpan. Simpan kembali sebelum mengumpulkan.');
 await api('attempt',{id:attempt.id,action:'submit'});attempt=await api('attempt?id='+attempt.id);showAttempt();
}
async function controlDialog(el){const action=el.dataset.kind;openDialog(`<h2>${{reset:'Reset login peserta',extend:'Tambah waktu',unblock:'Buka blokir',submit:'Paksa kumpulkan ujian'}[action]}</h2><p>${action==='reset'?'Sesi perangkat lama dicabut. Peserta perlu masuk kembali.':action==='submit'?'Ujian diselesaikan dan dinilai menggunakan jawaban yang tersimpan.':'Tindakan ini dicatat dalam riwayat ujian.'}</p><form id="control-form">${errorBox}${action==='extend'?field('minutes','Tambahan menit',10,'number','min="1" max="240" required'):''}${formActions('Terapkan')}</form>`);document.querySelector('#control-form').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async d=>{await api('control',{...d,action,id:Number(el.dataset.id),studentId:Number(el.dataset.student)});closeDialog();toast('Kontrol diterapkan.');await updateMonitor(cache.examSelection);});};}
function printCards(){const data=cache.students??[];openDialog(`<h2 class="no-print">Kartu peserta</h2><p class="no-print">Kartu menggunakan email login. Kata sandi tidak dicetak.</p><div>${data.map(st=>`<section class="panel" style="break-inside:avoid"><span class="eyebrow">${esc(me.settings.schoolName)}</span><h2>Kartu peserta ujian</h2><p><strong>${esc(st.fullName)}</strong><br>NISN: ${esc(st.nisn)}<br>Nomor: ${esc(st.examNumber)}<br>Kelas: ${esc(cache.classes?.find(c=>c.id===st.classId)?.name??st.classId)}<br>Email: ${esc(st.email)}</p></section>`).join('')}</div><div class="actions no-print">${button('Tutup','close')}${button('Cetak kartu','print')}</div>`);}
app.addEventListener('input',e=>{if(e.target.id==='table-search'){const query=e.target.value.toLocaleLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase().includes(query));}});
async function handleAction(el){
 const action=el.dataset.action;
 if(action==='close')return closeDialog();
 if(action==='forgot')return authScreen('forgot');if(action==='auth-login')return authScreen();
 if(action==='logout'){if(pending||saveFailed||pendingDraft)throw new Error('Simpan jawaban sebelum keluar.');if(me?.role==='siswa'&&me.profile)await api('release',{});await logout();me=null;cache={};return authScreen();}
 if(action==='refresh'){if(pending||saveFailed||pendingDraft)throw new Error('Simpan jawaban sebelum meninggalkan ujian.');cache={};return render();}
 if(action==='edit')return editResource(el.dataset.resource,el.dataset.id);
 if(action==='delete')return deleteResource(el.dataset.resource,el.dataset.id);
 if(action==='questions')return questionsPage(el.dataset.id);
 if(action==='question-edit')return questionEdit(el.dataset.bank,el.dataset.id);
 if(action==='question-delete'){openDialog(`<h2>Hapus soal?</h2><form id="delete-question">${errorBox}${formActions('Hapus soal')}</form>`);document.querySelector('#delete-question').onsubmit=e=>{e.preventDefault();submitForm(e.currentTarget,async()=>{await api('questions',{id:Number(el.dataset.id)},'DELETE');closeDialog();await questionsPage(cache.bankId);});};return;}
 if(action==='import')return el.dataset.resource==='students'?importStudents():openDialog(`<h2>Menyusun bank soal</h2><p>Tambahkan bank soal, lalu klik <strong>Soal</strong> untuk membuat atau mengimpor enam tipe soal. Format JSON dan Word .docx tersedia di editor.</p>${button('Tutup','close')}`);
 if(action==='import-questions')return importQuestions(el.dataset.id);
 if(action==='student-template')return download('template-siswa.csv',Papa.unparse([{email:'',nisn:'',examNumber:'',fullName:'',classId:'',gender:'L'}]),'text/csv');
 if(action==='question-template')return download('template-soal.json',Object.entries(examples).map(([type,ex],i)=>({number:i+1,type,text:'Tulis pertanyaan di sini',weight:1,...ex})));
 if(action==='word-template')return download('template-soal.txt','[SOAL]\nTulis pertanyaan di sini\n[TIPE] pilgan\n[BOBOT] 1\n[A] Opsi pertama\n[B] Opsi kedua\n[KUNCI] A\n[PEMBAHASAN] Alasan jawaban\n\n[SOAL]\nTulis pertanyaan uraian\n[TIPE] uraian\n[BOBOT] 5\n[OPSI] {}\n[KUNCI] Rubrik guru\n','text/plain');
 if(action==='enter')return enterExam(el.dataset.id);
 if(action==='prev-question'||action==='next-question'||action==='jump-question'){flushDraft();await saveChain;if(saveFailed)throw new Error('Simpan kembali jawaban sebelum berpindah soal.');qIndex=action==='prev-question'?qIndex-1:action==='next-question'?qIndex+1:Number(el.dataset.index);return showAttempt();}
 if(action==='retry-save'){flushDraft();for(const a of attempt.answers)queueSave(a);await saveChain;if(!saveFailed){document.querySelector('#save-error').textContent='';toast('Jawaban tersimpan.');}return;}
 if(action==='submit-attempt')return submitAttempt();if(action==='sync-attempt'){attempt=await api('attempt?id='+attempt.id);showAttempt();if(attempt.status==='in_progress')await openAttempt(attempt.id);return;}
 if(action==='font-small'||action==='font-large'){document.querySelector('.question-text').style.fontSize=action==='font-small'?'18px':'25px';return;}
 if(action==='control')return controlDialog(el);
 if(action==='disable-token'){await api('token',{examId:Number(el.dataset.id),active:false});cache.exams=null;await rows('exams');await loadExamPanel(el.dataset.id);toast('Token dinonaktifkan.');return;}
 if(action==='grade')return gradeDialog(el.dataset.id);
 if(action==='export-results')return download('nilai-ujian.csv',Papa.unparse(cache.results.participants.map(p=>({Nama:p.student,Nomor:p.examNumber,Nilai:p.score,Koreksi:p.graded?'Lengkap':'Menunggu',KKM:cache.results.kkm})),{escapeFormulae:true}),'text/csv;charset=utf-8');
 if(action==='print')return window.print();if(action==='cards')return printCards();
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();handleAction(el).catch(e=>showError(e));});
window.addEventListener('hashchange',async()=>{if(!me||recovery)return;if(pending||saveFailed||pendingDraft){toast('Simpan jawaban sebelum berpindah halaman.');return;}const next=location.hash.slice(1);if(navItems().includes(next)){page=next;await render();}});
window.addEventListener('beforeunload',e=>{if(pending||saveFailed||pendingDraft){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',async()=>{if(document.hidden&&attempt?.status==='in_progress'&&attempt.antiCheat){try{flushDraft();await saveChain;const data=await api('attempt',{id:attempt.id,action:'violation'});attempt.violations=data.violations??attempt.violations;if(data.status==='blocked'){attempt.status='blocked';showAttempt();}else toast('Perpindahan tab dicatat. Tetap di halaman ujian.');}catch(e){toast(e.message);}}});
async function init(){try{recovery=await handleAuthCallback();if(recovery?.type==='invite'||recovery?.type==='recovery'){authScreen('password');return;}const user=await getUser();if(user)await loadSession();else authScreen();}catch(e){authScreen('login',e.message);}}
init();
